"""SSD1675A (IL3897) monochrome e-paper controller.

Panels:
- E0213A09 (HINK): 104x212 monochrome

The waveform LUTs and analog/driver-voltage init values are panel data, passed
to the generic SSD1675 driver. BUSY is active-HIGH (the component default).
"""

from . import LutModel


class SSD1675(LutModel):
    def __init__(self, name, lut_full, lut_partial=None, **defaults):
        super().__init__(name, "EPaperSSD1675", lut_full, lut_partial, **defaults)

    def get_init_sequence(self, config):
        _, height = self.get_dimensions(config)
        return (
            (0x74, 0x54),  # set analog block control
            (0x7E, 0x3B),  # set digital block control
            (
                0x01,
                (height - 1) & 0xFF,
                (height - 1) >> 8,
                0x00,
            ),  # driver output control
            (0x3C, 0x03),  # border waveform
            (0x2C, 0x70),  # VCOM voltage
            (0x03, 0x15),  # gate driving voltage (19V)
            (0x04, 0x41, 0xA8, 0x32),  # source driving voltage (VSH1/VSH2/VSL)
            (0x3A, 0x30),  # dummy line
            (0x3B, 0x0A),  # gate time
        )


# E0213A09 waveform LUTs (based on GxEPD2 GxEPD2_213_B72).
# fmt: off
_E0213A09_LUT_FULL = [
    0x80, 0x60, 0x40, 0x00, 0x00, 0x00, 0x00,  # LUT0 BB
    0x10, 0x60, 0x20, 0x00, 0x00, 0x00, 0x00,  # LUT1 BW
    0x80, 0x60, 0x40, 0x00, 0x00, 0x00, 0x00,  # LUT2 WB
    0x10, 0x60, 0x20, 0x00, 0x00, 0x00, 0x00,  # LUT3 WW
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # LUT4 VCOM
    0x03, 0x03, 0x00, 0x00, 0x02,
    0x09, 0x09, 0x00, 0x00, 0x02,
    0x03, 0x03, 0x00, 0x00, 0x02,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
]
_E0213A09_LUT_PART = [
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # LUT0 BB
    0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # LUT1 BW
    0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # LUT2 WB
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # LUT3 WW
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # LUT4 VCOM
    0x0A, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00,
]
# fmt: on

SSD1675(
    "E0213A09",
    lut_full=_E0213A09_LUT_FULL,
    lut_partial=_E0213A09_LUT_PART,
    width=104,
    height=212,
    data_rate="4MHz",
    minimum_update_interval="1s",
)
